-- BLING six original collection concepts. Review before executing in Supabase SQL Editor.
-- No DELETE: preserves order history and product references.
BEGIN;
UPDATE public.products SET is_active = false, updated_at = NOW() WHERE is_active = true;
INSERT INTO public.products (slug,name,category,price_gbp,short,description,highlights,images,badge,is_active,updated_at)
VALUES
