('bling-age-defy-collection','BLING Age Defy Collection','Cosmetics',130.00,'A rose-gold inspired four-piece beauty ritual','A beautifully presented blush-pink collection featuring a proposed day cream, night cream, facial serum and eye cream. A thoughtful gift concept designed around a refined daily skincare experience.',ARRAY['Original BLING packaging concept','Gift-box presentation','Proposed contents subject to confirmation']::text[],ARRAY['/products/bling-collections/bling-age-defy-collection.webp','/products/bling-collections/bling-age-defy-collection-detail.webp']::text[],'New',true,NOW()),
('bling-renew-restore-collection','BLING Renew & Restore Collection','Cosmetics',130.00,'An emerald-green four-piece skincare edit','A rich green-and-gold gift box featuring a proposed cleansing gel, nourishing day cream, night cream and renewal mask. A complete, indulgent skincare ritual with an elevated presentation.',ARRAY['Original BLING packaging concept','Gift-box presentation','Proposed contents subject to confirmation']::text[],ARRAY['/products/bling-collections/bling-renew-restore-collection.webp','/products/bling-collections/bling-renew-restore-collection-detail.webp']::text[],'New',true,NOW()),
('bling-vital-perfection-collection','BLING Vital Perfection Collection','Cosmetics',130.00,'A violet four-piece skincare gift set','A regal purple-and-gold concept with proposed day cream, night cream, essence and eye cream, presented with a matching cosmetic pouch. An elegant gift for anyone who enjoys considered beauty rituals.',ARRAY['Original BLING packaging concept','Gift-box presentation','Proposed contents subject to confirmation']::text[],ARRAY['/products/bling-collections/bling-vital-perfection-collection.webp','/products/bling-collections/bling-vital-perfection-collection-detail.webp']::text[],'New',true,NOW()),
('bling-renewal-ritual-collection','BLING Renewal Ritual Collection','Cosmetics',130.00,'A peach-toned five-piece skincare ritual','A delicate peach-and-gold gift set featuring a proposed cleanser, day cream, night cream, serum and exfoliating polish. Designed as a coordinated beauty routine in a floral presentation box.',ARRAY['Original BLING packaging concept','Gift-box presentation','Proposed contents subject to confirmation']::text[],ARRAY['/products/bling-collections/bling-renewal-ritual-collection.webp','/products/bling-collections/bling-renewal-ritual-collection-detail.webp']::text[],'New',true,NOW()),
('bling-ultimate-lift-collection','BLING Ultimate Lift Collection','Cosmetics',130.00,'A midnight-blue four-piece skincare collection','A striking navy-and-gold gift concept with proposed day cream, night cream, serum and eye cream, accompanied by a matching cosmetic pouch. A distinctive luxury beauty gift presentation.',ARRAY['Original BLING packaging concept','Gift-box presentation','Proposed contents subject to confirmation']::text[],ARRAY['/products/bling-collections/bling-ultimate-lift-collection.webp','/products/bling-collections/bling-ultimate-lift-collection-detail.webp']::text[],'New',true,NOW())
ON CONFLICT (slug) DO UPDATE SET name=EXCLUDED.name, category=EXCLUDED.category,
 price_gbp=EXCLUDED.price_gbp, short=EXCLUDED.short, description=EXCLUDED.description,
 highlights=EXCLUDED.highlights, images=EXCLUDED.images, badge=EXCLUDED.badge,
 is_active=true, updated_at=NOW();
-- Ensure no unrelated products remain active, including any from earlier drafts.
UPDATE public.products SET is_active=false,updated_at=NOW()
 WHERE slug NOT IN ('bling-radiance-collection','bling-age-defy-collection','bling-renew-restore-collection','bling-vital-perfection-collection','bling-renewal-ritual-collection','bling-ultimate-lift-collection') AND is_active=true;
DO $$ BEGIN IF (SELECT COUNT(*) FROM public.products WHERE is_active=true) <> 6
 THEN RAISE EXCEPTION 'Expected exactly six active BLING products'; END IF; END $$;
COMMIT;
SELECT slug,name,price_gbp,images,is_active FROM public.products WHERE is_active=true ORDER BY name;
